package com.bankvaluehistory.ui;

import com.bankvaluehistory.BankValueHistoryConfig;
import com.bankvaluehistory.service.LocalDashboardServer;
import com.bankvaluehistory.service.SnapshotService;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Desktop;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.ActionEvent;
import java.io.IOException;
import java.nio.file.Path;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class BankValueHistoryPanel extends PluginPanel
{
    private final SnapshotService snapshotService;
    private final LocalDashboardServer dashboardServer;
    private final ClientThread clientThread;
    private final BankValueHistoryConfig config;

    private final JLabel statusValue = new JLabel();
    private final JLabel profileValue = new JLabel();
    private final JLabel dashboardValue = new JLabel();
    private final JLabel dataValue = new JLabel();
    private final JLabel settingsValue = new JLabel();
    private final JLabel hintValue = new JLabel();

    @Inject
    public BankValueHistoryPanel(SnapshotService snapshotService, LocalDashboardServer dashboardServer,
        ClientThread clientThread, BankValueHistoryConfig config)
    {
        this.snapshotService = snapshotService;
        this.dashboardServer = dashboardServer;
        this.clientThread = clientThread;
        this.config = config;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        root.add(section("Bank Value History", "Capture snapshots and control the local dashboard."));
        root.add(Box.createRigidArea(new Dimension(0, 8)));
        root.add(actionsSection());
        root.add(Box.createRigidArea(new Dimension(0, 8)));
        root.add(statusSection());
        root.add(Box.createRigidArea(new Dimension(0, 8)));
        root.add(settingsSection());
        root.add(Box.createVerticalGlue());

        add(root, BorderLayout.NORTH);
        refreshStatus();
    }

    private JPanel section(String title, String subtitle)
    {
        JPanel panel = card();
        JLabel titleLabel = new JLabel(title);
        titleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 16f));
        titleLabel.setToolTipText(title);

        JLabel subtitleLabel = new JLabel("<html><div style='width:250px'>" + escape(subtitle) + "</div></html>");
        subtitleLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
        subtitleLabel.setToolTipText(subtitle);

        panel.add(titleLabel);
        panel.add(Box.createRigidArea(new Dimension(0, 4)));
        panel.add(subtitleLabel);
        return panel;
    }

    private JPanel actionsSection()
    {
        JPanel panel = card();

        JLabel actionsLabel = sectionLabel("Actions");
        actionsLabel.setAlignmentX(CENTER_ALIGNMENT);
        actionsLabel.setHorizontalAlignment(SwingConstants.CENTER);
        panel.add(actionsLabel);

        panel.add(Box.createRigidArea(new Dimension(0, 6)));

        JPanel grid = new JPanel(new GridLayout(5, 1, 0, 4));
        grid.setOpaque(false);

        JButton capture = button("Capture snapshot");
        capture.addActionListener(this::captureNow);

        JButton open = button("Open dashboard");
        open.addActionListener(e -> {
            dashboardServer.ensureStarted();
            dashboardServer.openBrowser(snapshotService.getCurrentProfileKey());
            refreshStatus();
        });

        JButton restart = button("Restart dashboard");
        restart.addActionListener(e -> {
            dashboardServer.restart();
            refreshStatus();
        });

        JButton stop = button("Stop dashboard");
        stop.addActionListener(e -> {
            dashboardServer.stop();
            setHint("Dashboard stopped.");
            refreshStatus();
        });

        JButton folder = button("Open data folder");
        folder.addActionListener(e -> openDataFolder());

        grid.add(capture);
        grid.add(open);
        grid.add(restart);
        grid.add(stop);
        grid.add(folder);
        panel.add(grid);
        return panel;
    }

    private JPanel statusSection()
    {
        JPanel panel = card();

        JLabel statusLabel = sectionLabel("Status");
		statusLabel.setBorder(BorderFactory.createEmptyBorder(0, 20, 0, 0));
		panel.add(statusLabel);

		panel.add(Box.createRigidArea(new Dimension(0, 6)));
		panel.add(infoRow("State", statusValue));
		panel.add(Box.createRigidArea(new Dimension(0, 4)));
		panel.add(infoRow("Profile", profileValue));
		panel.add(Box.createRigidArea(new Dimension(0, 4)));
		panel.add(infoRow("Dashboard", dashboardValue));
		panel.add(Box.createRigidArea(new Dimension(0, 4)));
		panel.add(infoRow("Data path", dataValue));
		panel.add(Box.createRigidArea(new Dimension(0, 6)));
		hintValue.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		panel.add(hintValue);
		return panel;
    }

    private JPanel settingsSection()
    {
        JPanel panel = card();
        panel.add(sectionLabel("Config summary"));
        panel.add(Box.createRigidArea(new Dimension(0, 6)));
        settingsValue.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        panel.add(settingsValue);
        return panel;
    }

    private void captureNow(ActionEvent event)
    {
        setHint("Capturing bank snapshot...");
        clientThread.invoke(() -> {
            boolean ok = snapshotService.captureNow() != null;
            SwingUtilities.invokeLater(() -> {
                if (ok)
                {
                    if (config.openDashboardAfterCapture())
                    {
                        dashboardServer.ensureStarted();
                        dashboardServer.openBrowser(snapshotService.getCurrentProfileKey());
                    }
                    setHint("Snapshot captured. Refresh the browser if it is already open.");
                }
                else
                {
                    setHint("Open your bank first, and if a bank PIN is shown, enter it before capturing.");
                }
                refreshStatus();
            });
        });
    }

    public void refreshStatus()
    {
        Runnable update = () -> {
            boolean running = dashboardServer.isRunning();
            String profile = snapshotService.getCurrentProfileKey();
            Path baseDir = snapshotService.getSnapshotStore().getBaseDir();

            statusValue.setText(valueHtml(running ? "Running" : "Stopped"));
            statusValue.setForeground(running ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR);
            statusValue.setToolTipText(running ? "Dashboard is currently running." : "Dashboard is currently stopped.");

            profileValue.setText(valueHtml(profile));
            profileValue.setToolTipText(profile);

            dashboardValue.setText(valueHtml((running ? "Live" : "Offline") + " • " + dashboardServer.getBaseUrl()));
            dashboardValue.setToolTipText(dashboardServer.getBaseUrl());

            String fullPath = baseDir.toString();
            dataValue.setText(valueHtml(shortenMiddle(fullPath, 26)));
            dataValue.setToolTipText(fullPath);

            settingsValue.setText("<html><div style='width:250px'>"
                + bullet("Auto capture", shortYesNo(config.autoCapture()) + " after " + config.captureHour() + ":00")
                + bullet("Open after capture", shortYesNo(config.openDashboardAfterCapture()))
                + bullet("Auto-start web", shortYesNo(config.autoStartDashboard()))
                + bullet("Open on startup", shortYesNo(config.openDashboardOnStartup()))
                + bullet("Port", Integer.toString(config.webPort()))
                + bullet("Export icons", shortYesNo(config.exportIcons()))
                + bullet("Ignore zero-value", shortYesNo(config.ignoreZeroValueItems()))
                + "</div></html>");

            if (hintValue.getText() == null || hintValue.getText().trim().isEmpty())
            {
                setHint(running
                    ? "The local dashboard is ready."
                    : "Use Open dashboard or Restart dashboard to start the local site.");
            }
        };

        if (SwingUtilities.isEventDispatchThread())
        {
            update.run();
        }
        else
        {
            SwingUtilities.invokeLater(update);
        }
    }

    private JPanel card()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setAlignmentX(LEFT_ALIGNMENT);
        panel.setOpaque(true);
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_HOVER_COLOR),
            BorderFactory.createEmptyBorder(8, 8, 8, 8)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        return panel;
    }

    private JLabel sectionLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 13f));
        return label;
    }

    private JPanel infoRow(String labelText, JLabel valueLabel)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setOpaque(false);
        JLabel label = new JLabel(labelText);
        label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
        valueLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        row.add(label, BorderLayout.WEST);
        row.add(valueLabel, BorderLayout.CENTER);
        return row;
    }

    private JButton button(String text)
    {
        JButton button = new JButton(text);
        button.setFocusPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setMargin(new Insets(3, 8, 3, 8));
        button.setFont(button.getFont().deriveFont(Font.PLAIN, 12f));
        button.setPreferredSize(new Dimension(0, 24));
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        return button;
    }

    private void openDataFolder()
    {
        if (!Desktop.isDesktopSupported())
        {
            setHint("Desktop integration is not available on this system.");
            return;
        }

        try
        {
            Desktop.getDesktop().open(snapshotService.getSnapshotStore().getBaseDir().toFile());
            setHint("Opened the data folder.");
        }
        catch (IOException ex)
        {
            setHint("Unable to open the data folder.");
        }
    }

    private void setHint(String text)
    {
        hintValue.setText("<html><div style='width:250px'>" + escape(text) + "</div></html>");
        hintValue.setToolTipText(text);
    }

    private String valueHtml(String text)
    {
        return "<html><div style='width:170px'>" + escape(text) + "</div></html>";
    }

    private String bullet(String key, String value)
    {
        return "&#8226; <b>" + escape(key) + ":</b> " + escape(value) + "<br/>";
    }

    private String shortYesNo(boolean value)
    {
        return value ? "On" : "Off";
    }

    private String shortenMiddle(String value, int maxLen)
    {
        if (value == null || value.length() <= maxLen)
        {
            return value == null ? "" : value;
        }

        int keep = Math.max(6, (maxLen - 3) / 2);
        String start = value.substring(0, keep);
        String end = value.substring(value.length() - keep);
        return start + "..." + end;
    }

    private String escape(String value)
    {
        if (value == null)
        {
            return "";
        }

        return value
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;");
    }
}

package com.bankvaluehistory.service;

import com.bankvaluehistory.model.BankSnapshot;
import com.bankvaluehistory.model.BankTabSnapshot;
import com.bankvaluehistory.model.ItemSnapshot;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;

@Singleton
public class SnapshotStore
{
    private static final DateTimeFormatter FILE_TS = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH-mm-ss")
        .withZone(java.time.ZoneId.systemDefault());

    private final Path baseDir;

    public SnapshotStore()
    {
        this(RuneLite.RUNELITE_DIR.toPath().resolve("bank-value-tracker-web"));
    }

    public SnapshotStore(Path baseDir)
    {
        this.baseDir = baseDir;
    }

    public Path getBaseDir() { return baseDir; }
    public Path getIconsDir() { return baseDir.resolve("icons"); }
    public Path getDataDir() { return baseDir.resolve("data"); }
    public Path getProfileDir(String profileKey) { return getDataDir().resolve(profileKey); }
    public Path getSnapshotsDir(String profileKey) { return getProfileDir(profileKey).resolve("snapshots"); }
    public Path getImagesDir(String profileKey) { return getProfileDir(profileKey).resolve("images"); }
    public Path getLatestFile(String profileKey) { return getProfileDir(profileKey).resolve("latest.json.gz"); }
    public String getSnapshotDirectoryName(Instant capturedAt) { return FILE_TS.format(capturedAt); }
    public Path getSnapshotFile(String profileKey, Instant capturedAt) { return getSnapshotsDir(profileKey).resolve(getSnapshotDirectoryName(capturedAt) + ".json.gz"); }
    public Path getSnapshotImageFile(String profileKey, Instant capturedAt) { return getImagesDir(profileKey).resolve(getSnapshotDirectoryName(capturedAt) + ".png"); }
    public Path getSnapshotIconsDir(String profileKey, Instant capturedAt) { return getProfileDir(profileKey).resolve("icons").resolve(getSnapshotDirectoryName(capturedAt)); }

    private Path getLegacyLatestFile(String profileKey)
    {
        return getProfileDir(profileKey).resolve("latest.json");
    }

    public void ensureDirectories(String profileKey) throws IOException
    {
        Files.createDirectories(getIconsDir());
        Files.createDirectories(getSnapshotsDir(profileKey));
        Files.createDirectories(getImagesDir(profileKey));
    }

    public void save(BankSnapshot snapshot) throws IOException
    {
        ensureDirectories(snapshot.getProfileKey());
        String json = toJson(snapshot);
        writeJson(getSnapshotFile(snapshot.getProfileKey(), snapshot.getCapturedAt()), json);
        writeJson(getLatestFile(snapshot.getProfileKey()), json);
    }

    public boolean deleteSnapshot(String profileKey, String capturedAt) throws IOException
    {
        if (profileKey == null || profileKey.trim().isEmpty() || capturedAt == null || capturedAt.trim().isEmpty())
        {
            return false;
        }

        Optional<Path> snapshotFile = findSnapshotFile(profileKey, capturedAt);
        if (!snapshotFile.isPresent())
        {
            return false;
        }

        String json = readJson(snapshotFile.get());

        deleteFileIfInside(getSnapshotsDir(profileKey), snapshotFile.get());
        deleteBankImageFromSnapshotJson(json);
        deleteNewSnapshotIconFoldersFromSnapshotJson(json);
        deleteNewSnapshotIconFolderFromTimestamp(profileKey, capturedAt);
        rebuildLatestSnapshot(profileKey);

        return true;
    }

    private Optional<Path> findSnapshotFile(String profileKey, String capturedAt)
    {
        Path dir = getSnapshotsDir(profileKey);
        if (!Files.isDirectory(dir))
        {
            return Optional.empty();
        }

        try (Stream<Path> stream = Files.list(dir))
        {
            List<Path> candidates = stream
                .filter(this::isSnapshotJsonFile)
                .sorted(Comparator.comparing(Path::getFileName))
                .collect(Collectors.toList());

            for (Path path : candidates)
            {
                try
                {
                    String json = readJson(path);
                    if (json.contains("\"capturedAt\":\"" + escapeJson(capturedAt) + "\""))
                    {
                        return Optional.of(path);
                    }
                }
                catch (IOException ignored)
                {
                    // ignore unreadable snapshot files
                }
            }
        }
        catch (IOException ignored)
        {
            // fall through
        }

        return Optional.empty();
    }

    private void rebuildLatestSnapshot(String profileKey) throws IOException
    {
        Path dir = getSnapshotsDir(profileKey);
        Optional<Path> newest = Optional.empty();

        if (Files.isDirectory(dir))
        {
            try (Stream<Path> stream = Files.list(dir))
            {
                newest = stream
                    .filter(this::isSnapshotJsonFile)
                    .sorted(Comparator.comparing((Path path) -> path.getFileName().toString()).reversed())
                    .findFirst();
            }
        }

        Path latest = getLatestFile(profileKey);
        Path legacyLatest = getLegacyLatestFile(profileKey);

        if (newest.isPresent())
        {
            writeJson(latest, readJson(newest.get()));
            deleteFileIfInside(getProfileDir(profileKey), legacyLatest);
        }
        else
        {
            deleteFileIfInside(getProfileDir(profileKey), latest);
            deleteFileIfInside(getProfileDir(profileKey), legacyLatest);
        }
    }

    private void deleteBankImageFromSnapshotJson(String json) throws IOException
    {
        String bankImagePath = extractJsonString(json, "bankImagePath");
        if (bankImagePath == null || !bankImagePath.startsWith("/data/"))
        {
            return;
        }

        Path path = getDataDir().resolve(bankImagePath.substring("/data/".length())).normalize();
        deleteFileIfInside(getDataDir(), path);
    }

    private void deleteNewSnapshotIconFolderFromTimestamp(String profileKey, String capturedAt) throws IOException
    {
        try
        {
            Instant instant = Instant.parse(capturedAt);
            deleteDirectoryIfInside(getIconsDir(), getSnapshotIconsDir(profileKey, instant));
        }
        catch (RuntimeException ignored)
        {
            // Older or malformed timestamps are handled by iconPath cleanup.
        }
    }

    private void deleteNewSnapshotIconFoldersFromSnapshotJson(String json) throws IOException
    {
        for (String iconPath : extractIconPaths(json))
        {
            String normalized = iconPath.replace('\\', '/');

            if (normalized.startsWith("/data/"))
            {
                String relative = normalized.substring("/data/".length());
                String[] parts = relative.split("/");
                if (parts.length >= 4 && "icons".equals(parts[1]))
                {
                    Path iconFile = getDataDir().resolve(relative).normalize();
                    Path snapshotIconDir = iconFile.getParent();
                    if (snapshotIconDir != null)
                    {
                        deleteDirectoryIfInside(getDataDir(), snapshotIconDir);
                    }
                }
                continue;
            }

            if (normalized.startsWith("/icons/"))
            {
                String relative = normalized.substring("/icons/".length());
                String[] parts = relative.split("/");
                if (parts.length < 3)
                {
                    // Legacy global icon style, for example /icons/4151.png.
                    // Do not delete because old snapshots can share these icons.
                    continue;
                }

                // Cleanup compatibility for the previous attempted structure:
                // /icons/<profile>/<snapshot>/<file>.png
                Path iconFile = getIconsDir().resolve(relative).normalize();
                Path snapshotIconDir = iconFile.getParent();
                if (snapshotIconDir != null)
                {
                    deleteDirectoryIfInside(getIconsDir(), snapshotIconDir);
                }
            }
        }
    }

    private List<String> extractIconPaths(String json)
    {
        List<String> paths = new ArrayList<>();
        if (json == null || json.isEmpty())
        {
            return paths;
        }

        String marker = "\"iconPath\":\"";
        int index = 0;
        while ((index = json.indexOf(marker, index)) >= 0)
        {
            int start = index + marker.length();
            int end = json.indexOf('"', start);
            if (end <= start)
            {
                break;
            }
            paths.add(json.substring(start, end).replace("\\/", "/"));
            index = end + 1;
        }
        return paths;
    }

    private String extractJsonString(String json, String key)
    {
        if (json == null || key == null)
        {
            return null;
        }

        String marker = "\"" + key + "\":\"";
        int start = json.indexOf(marker);
        if (start < 0)
        {
            return null;
        }

        start += marker.length();
        StringBuilder value = new StringBuilder();
        boolean escaped = false;
        for (int i = start; i < json.length(); i++)
        {
            char ch = json.charAt(i);
            if (escaped)
            {
                value.append(ch);
                escaped = false;
                continue;
            }
            if (ch == '\\')
            {
                escaped = true;
                continue;
            }
            if (ch == '"')
            {
                return value.toString();
            }
            value.append(ch);
        }
        return null;
    }

    private void deleteFileIfInside(Path root, Path path) throws IOException
    {
        Path normalizedRoot = root.normalize();
        Path normalizedPath = path.normalize();
        if (normalizedPath.startsWith(normalizedRoot) && Files.isRegularFile(normalizedPath))
        {
            Files.deleteIfExists(normalizedPath);
        }
    }

    private void deleteDirectoryIfInside(Path root, Path dir) throws IOException
    {
        Path normalizedRoot = root.normalize();
        Path normalizedDir = dir.normalize();
        if (!normalizedDir.startsWith(normalizedRoot) || normalizedDir.equals(normalizedRoot) || !Files.isDirectory(normalizedDir))
        {
            return;
        }

        try (Stream<Path> walk = Files.walk(normalizedDir))
        {
            List<Path> paths = walk
                .sorted(Comparator.reverseOrder())
                .collect(Collectors.toList());
            for (Path path : paths)
            {
                Files.deleteIfExists(path);
            }
        }
    }

    public boolean hasSnapshotForDay(String profileKey, LocalDate day)
    {
        return readLatestJson(profileKey)
            .map(json -> json.contains("\"day\":\"" + day + "\""))
            .orElse(false);
    }

    public Optional<String> readLatestJson(String profileKey)
    {
        Path latest = getLatestFile(profileKey);
        if (Files.exists(latest))
        {
            try
            {
                return Optional.of(readJson(latest));
            }
            catch (IOException ex)
            {
                return Optional.empty();
            }
        }

        Path legacyLatest = getLegacyLatestFile(profileKey);
        if (Files.exists(legacyLatest))
        {
            try
            {
                return Optional.of(readJson(legacyLatest));
            }
            catch (IOException ex)
            {
                return Optional.empty();
            }
        }

        return Optional.empty();
    }

    public String buildSnapshotsArrayJson(String profileKey)
    {
        Path dir = getSnapshotsDir(profileKey);
        if (!Files.isDirectory(dir)) return "[]";

        try (Stream<Path> stream = Files.list(dir))
        {
            return stream
                .filter(this::isSnapshotJsonFile)
                .sorted(Comparator.comparing(Path::getFileName))
                .map(path -> {
                    try
                    {
                        return readJson(path);
                    }
                    catch (IOException ex)
                    {
                        return null;
                    }
                })
                .filter(json -> json != null && !json.trim().isEmpty())
                .collect(Collectors.joining(",", "[", "]"));
        }
        catch (IOException ex)
        {
            return "[]";
        }
    }

    public String resolveProfileOrLatest(String preferred)
    {
        String fallback = isSafeProfileKey(preferred) ? preferred : "unknown";
        if (isSafeProfileKey(preferred) && Files.isDirectory(getProfileDir(preferred))) return preferred;

        Path dataDir = getDataDir();
        if (!Files.isDirectory(dataDir)) return fallback;

        try (Stream<Path> stream = Files.list(dataDir))
        {
            return stream.filter(Files::isDirectory)
                .map(path -> path.getFileName().toString())
                .filter(this::isSafeProfileKey)
                .max(Comparator.comparingLong(name -> latestModifiedTime(getProfileDir(name))))
                .orElse(fallback);
        }
        catch (IOException ex)
        {
            return fallback;
        }
    }

    private boolean isSafeProfileKey(String profileKey)
    {
        if (profileKey == null || profileKey.trim().isEmpty() || profileKey.length() > 128)
        {
            return false;
        }

        return !profileKey.contains("..")
            && !profileKey.contains("/")
            && !profileKey.contains("\\")
            && !profileKey.contains(":")
            && profileKey.chars().allMatch(ch -> ch >= 32 && ch != 127);
    }

    private long latestModifiedTime(Path profileDir)
    {
        try
        {
            Path latestGz = profileDir.resolve("latest.json.gz");
            if (Files.exists(latestGz)) return Files.getLastModifiedTime(latestGz).toMillis();

            Path latestJson = profileDir.resolve("latest.json");
            if (Files.exists(latestJson)) return Files.getLastModifiedTime(latestJson).toMillis();

            return Files.getLastModifiedTime(profileDir).toMillis();
        }
        catch (IOException ex)
        {
            return 0L;
        }
    }

    public String statusJson(String profileKey, int port)
    {
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        appendJsonField(sb, "currentProfile", profileKey).append(',');
        appendJsonField(sb, "baseDir", baseDir.toString()).append(',');
        appendJsonField(sb, "dashboardUrl", "http://127.0.0.1:" + port + "/");
        sb.append('}');
        return sb.toString();
    }

    private boolean isSnapshotJsonFile(Path path)
    {
        String filename = path.getFileName().toString().toLowerCase();
        return filename.endsWith(".json") || filename.endsWith(".json.gz");
    }

    private void writeJson(Path path, String json) throws IOException
    {
        if (path.getFileName().toString().endsWith(".gz"))
        {
            try (OutputStream out = new GZIPOutputStream(Files.newOutputStream(path));
                 BufferedWriter writer = new BufferedWriter(new java.io.OutputStreamWriter(out, StandardCharsets.UTF_8)))
            {
                writer.write(json);
            }
            return;
        }

        Files.writeString(path, json, StandardCharsets.UTF_8);
    }

    private String readJson(Path path) throws IOException
    {
        String json;
        if (path.getFileName().toString().endsWith(".gz"))
        {
            try (InputStream in = new GZIPInputStream(Files.newInputStream(path));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
            {
                json = reader.lines().collect(Collectors.joining("\n"));
            }
        }
        else
        {
            json = Files.readString(path, StandardCharsets.UTF_8);
        }

        return repairKnownBatch3SnapshotJson(json);
    }

    private static String repairKnownBatch3SnapshotJson(String json)
    {
        if (json == null)
        {
            return null;
        }

        String trimmed = json.trim();
        if (trimmed.endsWith("]]}") && trimmed.contains("\"equipmentItems\""))
        {
            int removeIndex = json.lastIndexOf("]}");
            if (removeIndex > 0)
            {
                return json.substring(0, removeIndex) + "}";
            }
        }

        return json;
    }

    public static String toJson(BankSnapshot snapshot)
    {
        StringBuilder sb = new StringBuilder(16384);
        sb.append('{');
        appendJsonField(sb, "profileKey", snapshot.getProfileKey()).append(',');
        appendJsonField(sb, "day", snapshot.getDay().toString()).append(',');
        appendJsonField(sb, "capturedAt", snapshot.getCapturedAt().toString()).append(',');
        appendJsonField(sb, "totalGe", snapshot.getTotalGe()).append(',');
        appendJsonField(sb, "totalHa", snapshot.getTotalHa()).append(',');
        appendJsonField(sb, "bankGe", snapshot.getBankGe()).append(',');
        appendJsonField(sb, "bankHa", snapshot.getBankHa()).append(',');
        appendJsonField(sb, "inventoryGe", snapshot.getInventoryGe()).append(',');
        appendJsonField(sb, "inventoryHa", snapshot.getInventoryHa()).append(',');
        appendJsonField(sb, "equipmentGe", snapshot.getEquipmentGe()).append(',');
        appendJsonField(sb, "equipmentHa", snapshot.getEquipmentHa()).append(',');
        appendJsonField(sb, "combinedGe", snapshot.getCombinedGe()).append(',');
        appendJsonField(sb, "combinedHa", snapshot.getCombinedHa()).append(',');
        appendJsonField(sb, "bankImagePath", snapshot.getBankImagePath()).append(',');
        appendJsonField(sb, "bankImageWidth", snapshot.getBankImageWidth()).append(',');
        appendJsonField(sb, "bankImageHeight", snapshot.getBankImageHeight()).append(',');
        sb.append("\"bankTabs\":[");
        boolean firstTab = true;
        for (BankTabSnapshot tab : snapshot.getBankTabs())
        {
            if (!firstTab) sb.append(',');
            firstTab = false;
            sb.append('{');
            appendJsonField(sb, "index", tab.getIndex()).append(',');
            appendJsonField(sb, "name", tab.getName()).append(',');
            appendJsonField(sb, "count", tab.getCount());
            sb.append('}');
        }
        sb.append(']');
        appendItemArray(sb, "items", snapshot.getItems());
        appendItemArray(sb, "inventoryItems", snapshot.getInventoryItems());
        appendItemArray(sb, "equipmentItems", snapshot.getEquipmentItems());
        sb.append('}');
        return sb.toString();
    }

    private static void appendItemArray(StringBuilder sb, String fieldName, java.util.List<ItemSnapshot> items)
    {
        sb.append(',').append('"').append(escapeJson(fieldName)).append('"').append(':').append('[');
        boolean first = true;
        for (ItemSnapshot item : items)
        {
            if (!first) sb.append(',');
            first = false;
            sb.append('{');
            appendJsonField(sb, "itemId", item.getItemId()).append(',');
            appendJsonField(sb, "canonicalItemId", item.getCanonicalItemId()).append(',');
            appendJsonField(sb, "name", item.getName()).append(',');
            appendJsonField(sb, "quantity", item.getQuantity()).append(',');
            appendJsonField(sb, "geUnitPrice", item.getGeUnitPrice()).append(',');
            appendJsonField(sb, "geTotal", item.getGeTotal()).append(',');
            appendJsonField(sb, "haUnitPrice", item.getHaUnitPrice()).append(',');
            appendJsonField(sb, "haTotal", item.getHaTotal()).append(',');
            appendJsonField(sb, "slotIndex", item.getSlotIndex()).append(',');
            appendJsonField(sb, "tabIndex", item.getTabIndex()).append(',');
            appendJsonField(sb, "tabName", item.getTabName()).append(',');
            appendJsonField(sb, "iconPath", item.getIconPath()).append(',');
            appendJsonField(sb, "placeholder", item.isPlaceholder() ? 1 : 0).append(',');
            appendJsonField(sb, "layoutX", item.getLayoutX()).append(',');
            appendJsonField(sb, "layoutY", item.getLayoutY()).append(',');
            appendJsonField(sb, "layoutW", item.getLayoutW()).append(',');
            appendJsonField(sb, "layoutH", item.getLayoutH());
            sb.append('}');
        }
        sb.append(']');
    }

    private static StringBuilder appendJsonField(StringBuilder sb, String name, String value)
    {
        sb.append('"').append(escapeJson(name)).append('"').append(':');
        if (value == null) sb.append("null"); else sb.append('"').append(escapeJson(value)).append('"');
        return sb;
    }

    private static StringBuilder appendJsonField(StringBuilder sb, String name, long value)
    {
        sb.append('"').append(escapeJson(name)).append('"').append(':').append(value);
        return sb;
    }

    private static String escapeJson(String value)
    {
        if (value == null)
        {
            return "";
        }

        return value
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\n", "\\n")
            .replace("\r", "\\r");
    }
}

package com.bankvaluehistory.service;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class IconExportService
{
    private static final Logger log = LoggerFactory.getLogger(IconExportService.class);

    private final ItemManager itemManager;
    private final SnapshotStore snapshotStore;

    @Inject
    public IconExportService(ItemManager itemManager, SnapshotStore snapshotStore)
    {
        this.itemManager = itemManager;
        this.snapshotStore = snapshotStore;
    }

    public String exportSnapshotIcon(String profileKey, Instant capturedAt, int itemId, int canonicalItemId, int quantity, boolean placeholder)
    {
        int safeQuantity = Math.max(0, quantity);
        String fileName = buildIconFileName(itemId, canonicalItemId, safeQuantity, placeholder);
        Path snapshotDir = snapshotStore.getSnapshotIconsDir(profileKey, capturedAt);
        Path file = snapshotDir.resolve(fileName);

        if (Files.exists(file))
        {
            return buildSnapshotIconUrl(profileKey, capturedAt, fileName);
        }

        try
        {
            Files.createDirectories(snapshotDir);
            log.debug("Exporting snapshot icon to {}", file);

            Path legacyFile = snapshotStore.getIconsDir().resolve(fileName);
            if (Files.exists(legacyFile))
            {
                Files.copy(legacyFile, file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.COPY_ATTRIBUTES);
                return buildSnapshotIconUrl(profileKey, capturedAt, fileName);
            }

            int imageItemId = itemId > 0 ? itemId : canonicalItemId;
            int imageQuantity = Math.max(1, safeQuantity);
            boolean stackableQuantity = !placeholder && imageQuantity > 1;

            BufferedImage image = itemManager.getImage(imageItemId, imageQuantity, stackableQuantity);
            if (image != null)
            {
                ImageIO.write(image, "png", file.toFile());
            }
        }
        catch (IOException ex)
        {
            log.warn("Unable to export icon for item {} (canonical {}, quantity {}, placeholder {})",
                itemId, canonicalItemId, quantity, placeholder, ex);
        }

        return buildSnapshotIconUrl(profileKey, capturedAt, fileName);
    }

    public String exportSnapshotIcon(int itemId, int canonicalItemId, int quantity, boolean placeholder)
    {
        int safeQuantity = Math.max(0, quantity);
        String fileName = buildIconFileName(itemId, canonicalItemId, safeQuantity, placeholder);
        Path file = snapshotStore.getIconsDir().resolve(fileName);

        if (Files.exists(file))
        {
            return "/icons/" + file.getFileName().toString();
        }

        // Legacy/global icon export is intentionally read-only now.
        // New captures must use exportSnapshotIcon(profileKey, capturedAt, ...)
        // so icons are written under data/<profile>/icons/<snapshot-date>/.
        log.warn("Legacy icon export was called for item {} (canonical {}, quantity {}, placeholder {}) without profile/snapshot context. No global icon was written.",
            itemId, canonicalItemId, quantity, placeholder);

        return "";
    }

    private String buildSnapshotIconUrl(String profileKey, Instant capturedAt, String fileName)
    {
        return "/data/"
            + encodePathSegment(profileKey)
            + "/icons/"
            + encodePathSegment(snapshotStore.getSnapshotDirectoryName(capturedAt))
            + "/"
            + encodePathSegment(fileName);
    }

    private String encodePathSegment(String value)
    {
        return URLEncoder.encode(value == null ? "unknown" : value, StandardCharsets.UTF_8)
            .replace("+", "%20");
    }

    private String buildIconFileName(int itemId, int canonicalItemId, int quantity, boolean placeholder)
    {
        StringBuilder sb = new StringBuilder(64);
        sb.append(itemId > 0 ? itemId : canonicalItemId);
        sb.append("__q").append(Math.max(0, quantity));
        if (placeholder)
        {
            sb.append("__ph");
        }
        sb.append(".png");
        return sb.toString();
    }
}

package com.bankvaluehistory.service;

import java.io.IOException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class WikiPriceService
{
    private static final Logger log = LoggerFactory.getLogger(WikiPriceService.class);
    private static final URI LATEST_URI = URI.create("https://prices.runescape.wiki/api/v1/osrs/latest");
    private static final URI MAPPING_URI = URI.create("https://prices.runescape.wiki/api/v1/osrs/mapping");
    private static final String TIMESERIES_BASE = "https://prices.runescape.wiki/api/v1/osrs/timeseries";
    private static final Pattern ITEM_PATTERN = Pattern.compile("\"(\\d+)\"\\s*:\\s*\\{\\s*\"high\"\\s*:\\s*(null|\\d+)\\s*,\\s*\"highTime\"\\s*:\\s*(null|\\d+)\\s*,\\s*\"low\"\\s*:\\s*(null|\\d+)\\s*,\\s*\"lowTime\"\\s*:\\s*(null|\\d+)\\s*\\}");
    private static final String USER_AGENT = "bank-value-tracker/0.7 (local RuneLite plugin dashboard)";

    private final HttpClient httpClient = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(10))
        .followRedirects(HttpClient.Redirect.NORMAL)
        .build();

    private final AtomicBoolean refreshInFlight = new AtomicBoolean(false);
    private final ConcurrentHashMap<Integer, PricePoint> latestPrices = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, CachedJson> timeseriesCache = new ConcurrentHashMap<>();
    private volatile CachedJson mappingCache;

    private ScheduledExecutorService executor;
    private volatile Instant lastRefresh = Instant.EPOCH;

    public synchronized void start()
    {
        if (executor != null)
        {
            return;
        }

        executor = Executors.newSingleThreadScheduledExecutor();
        executor.execute(this::refreshNow);
        executor.scheduleAtFixedRate(this::refreshNow, 5, 5, TimeUnit.MINUTES);
    }

    public synchronized void stop()
    {
        if (executor != null)
        {
            executor.shutdown();
            executor = null;
        }
    }

    public void refreshAsyncIfStale(Duration maxAge)
    {
        if (Duration.between(lastRefresh, Instant.now()).compareTo(maxAge) > 0 && executor != null)
        {
            executor.execute(this::refreshNow);
        }
    }

    public Instant getLastRefresh()
    {
        return lastRefresh;
    }

    public String buildSubsetJson(Collection<Integer> ids)
    {
        Set<Integer> uniqueIds = ids == null ? Collections.emptySet() : Set.copyOf(ids);
        StringBuilder sb = new StringBuilder(256 + uniqueIds.size() * 72);
        sb.append('{');
        appendJsonField(sb, "fetchedAt", lastRefresh.equals(Instant.EPOCH) ? null : lastRefresh.toString()).append(',');
        appendJsonField(sb, "source", LATEST_URI.toString()).append(',');
        sb.append("\"data\":{");
        boolean first = true;
        for (Integer id : uniqueIds)
        {
            if (id == null)
            {
                continue;
            }
            PricePoint point = latestPrices.get(id);
            if (point == null)
            {
                continue;
            }
            if (!first)
            {
                sb.append(',');
            }
            first = false;
            sb.append('"').append(id.intValue()).append('"').append(':').append('{');
            appendJsonField(sb, "high", point.high).append(',');
            appendJsonField(sb, "highTime", point.highTime).append(',');
            appendJsonField(sb, "low", point.low).append(',');
            appendJsonField(sb, "lowTime", point.lowTime).append(',');
            appendJsonField(sb, "mid", point.mid());
            sb.append('}');
        }
        sb.append("}}");
        return sb.toString();
    }

    public String fetchTimeseriesJson(int itemId, String timestep)
    {
        String normalized = normalizeTimestep(timestep);
        String key = itemId + ":" + normalized;
        CachedJson cached = timeseriesCache.get(key);
        if (cached != null && Duration.between(cached.fetchedAt, Instant.now()).toMinutes() < 30)
        {
            return cached.body;
        }

        try
        {
            String uri = TIMESERIES_BASE
                + "?id=" + itemId
                + "&timestep=" + URLEncoder.encode(normalized, StandardCharsets.UTF_8);
            HttpResponse<String> response = httpClient.send(buildJsonRequest(URI.create(uri), Duration.ofSeconds(20)), HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() / 100 == 2 && response.body() != null && !response.body().isEmpty())
            {
                String body = response.body();
                timeseriesCache.put(key, new CachedJson(body, Instant.now()));
                return body;
            }
        }
        catch (IOException | InterruptedException ex)
        {
            log.debug("Unable to fetch wiki timeseries for {} {}", itemId, normalized, ex);
        }

        return "{\"data\":[]}";
    }

    private String normalizeTimestep(String timestep)
    {
        if (timestep == null)
        {
            return "24h";
        }
        switch (timestep)
        {
            case "5m":
            case "1h":
            case "6h":
            case "24h":
                return timestep;
            default:
                return "24h";
        }
    }


    public String fetchMappingJson()
    {
        CachedJson cached = mappingCache;
        if (cached != null && Duration.between(cached.fetchedAt, Instant.now()).toHours() < 12)
        {
            return cached.body;
        }

        try
        {
            HttpResponse<String> response = httpClient.send(buildJsonRequest(MAPPING_URI, Duration.ofSeconds(20)), HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() / 100 == 2 && response.body() != null && !response.body().isEmpty())
            {
                mappingCache = new CachedJson(response.body(), Instant.now());
                return response.body();
            }
        }
        catch (IOException | InterruptedException ex)
        {
            log.debug("Unable to fetch wiki mapping", ex);
        }

        return cached != null ? cached.body : "[]";
    }

    private HttpRequest buildJsonRequest(URI uri, Duration timeout)
    {
        return HttpRequest.newBuilder(uri)
            .timeout(timeout)
            .header("User-Agent", USER_AGENT)
            .header("x-user-agent", USER_AGENT)
            .header("Accept", "application/json")
            .GET()
            .build();
    }

    private void refreshNow()
    {
        if (!refreshInFlight.compareAndSet(false, true))
        {
            return;
        }

        try
        {
            HttpResponse<String> response = httpClient.send(buildJsonRequest(LATEST_URI, Duration.ofSeconds(20)), HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() / 100 != 2)
            {
                log.debug("Wiki price refresh returned HTTP {}", response.statusCode());
                return;
            }

            Map<Integer, PricePoint> parsed = parseLatest(response.body());
            if (!parsed.isEmpty())
            {
                latestPrices.clear();
                latestPrices.putAll(parsed);
                lastRefresh = Instant.now();
            }
        }
        catch (IOException | InterruptedException ex)
        {
            log.debug("Unable to refresh live wiki prices", ex);
        }
        finally
        {
            refreshInFlight.set(false);
        }
    }

    private Map<Integer, PricePoint> parseLatest(String body)
    {
        if (body == null || body.isEmpty())
        {
            return Collections.emptyMap();
        }

        Map<Integer, PricePoint> map = new HashMap<>();
        Matcher matcher = ITEM_PATTERN.matcher(body);
        while (matcher.find())
        {
            int id = Integer.parseInt(matcher.group(1));
            int high = parseNullableInt(matcher.group(2));
            long highTime = parseNullableLong(matcher.group(3));
            int low = parseNullableInt(matcher.group(4));
            long lowTime = parseNullableLong(matcher.group(5));
            map.put(id, new PricePoint(high, highTime, low, lowTime));
        }
        return map;
    }

    private int parseNullableInt(String value)
    {
        return value == null || "null".equals(value) ? 0 : Integer.parseInt(value);
    }

    private long parseNullableLong(String value)
    {
        return value == null || "null".equals(value) ? 0L : Long.parseLong(value);
    }

    private static StringBuilder appendJsonField(StringBuilder sb, String name, String value)
    {
        sb.append('"').append(escape(name)).append('"').append(':');
        if (value == null)
        {
            sb.append("null");
        }
        else
        {
            sb.append('"').append(escape(value)).append('"');
        }
        return sb;
    }

    private static StringBuilder appendJsonField(StringBuilder sb, String name, long value)
    {
        sb.append('"').append(escape(name)).append('"').append(':').append(value);
        return sb;
    }

    private static String escape(String value)
    {
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static class PricePoint
    {
        private final int high;
        private final long highTime;
        private final int low;
        private final long lowTime;

        private PricePoint(int high, long highTime, int low, long lowTime)
        {
            this.high = high;
            this.highTime = highTime;
            this.low = low;
            this.lowTime = lowTime;
        }

        private long mid()
        {
            if (high > 0 && low > 0)
            {
                return (high + (long) low) / 2L;
            }
            return high > 0 ? high : low;
        }
    }

    private static class CachedJson
    {
        private final String body;
        private final Instant fetchedAt;

        private CachedJson(String body, Instant fetchedAt)
        {
            this.body = body;
            this.fetchedAt = fetchedAt;
        }
    }
}

package com.bankvaluehistory.service;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Comparator;
import java.util.Optional;
import java.util.stream.Stream;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class BankImageRenderer
{
    private static final Logger log = LoggerFactory.getLogger(BankImageRenderer.class);

    private final SnapshotStore snapshotStore;
    private final Client client;

    @Inject
    public BankImageRenderer(SnapshotStore snapshotStore, Client client)
    {
        this.snapshotStore = snapshotStore;
        this.client = client;
    }

    public CaptureResult capture(String profileKey, Instant capturedAt, Rectangle captureBounds)
    {
        try
        {
            snapshotStore.ensureDirectories(profileKey);
            BufferedImage image = createCapture(captureBounds);

            Path reusable = findReusableImage(profileKey, image).orElse(null);
            if (reusable != null)
            {
                return new CaptureResult(
                    "/data/" + profileKey + "/images/" + reusable.getFileName().toString(),
                    image.getWidth(),
                    image.getHeight()
                );
            }

            Path file = snapshotStore.getSnapshotImageFile(profileKey, capturedAt);
            ImageIO.write(image, "png", file.toFile());
            return new CaptureResult(
                "/data/" + profileKey + "/images/" + file.getFileName().toString(),
                image.getWidth(),
                image.getHeight()
            );
        }
        catch (IOException | RuntimeException ex)
        {
            log.warn("Unable to capture bank image for {}", profileKey, ex);
            return new CaptureResult(null, 0, 0);
        }
    }

    private Optional<Path> findReusableImage(String profileKey, BufferedImage currentImage)
    {
        Path imagesDir = snapshotStore.getImagesDir(profileKey);
        if (!Files.isDirectory(imagesDir))
        {
            return Optional.empty();
        }

        try (Stream<Path> stream = Files.list(imagesDir))
        {
            Path latest = stream
                .filter(this::isPngFile)
                .max(Comparator.comparingLong(this::lastModifiedSafe))
                .orElse(null);

            if (latest == null)
            {
                return Optional.empty();
            }

            BufferedImage existing = ImageIO.read(latest.toFile());
            if (existing == null)
            {
                return Optional.empty();
            }

            return imagesEqual(existing, currentImage) ? Optional.of(latest) : Optional.empty();
        }
        catch (IOException ex)
        {
            log.debug("Unable to inspect previous bank image for {}", profileKey, ex);
            return Optional.empty();
        }
    }

    private boolean isPngFile(Path path)
    {
        String name = path.getFileName().toString().toLowerCase();
        return name.endsWith(".png");
    }

    private long lastModifiedSafe(Path path)
    {
        try
        {
            return Files.getLastModifiedTime(path).toMillis();
        }
        catch (IOException ex)
        {
            return 0L;
        }
    }

    private boolean imagesEqual(BufferedImage a, BufferedImage b)
    {
        if (a == null || b == null)
        {
            return false;
        }

        if (a.getWidth() != b.getWidth() || a.getHeight() != b.getHeight())
        {
            return false;
        }

        for (int y = 0; y < a.getHeight(); y++)
        {
            for (int x = 0; x < a.getWidth(); x++)
            {
                if (a.getRGB(x, y) != b.getRGB(x, y))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private BufferedImage createCapture(Rectangle captureBounds)
    {
        Component canvas = client.getCanvas();
        if (canvas == null || canvas.getWidth() <= 0 || canvas.getHeight() <= 0)
        {
            return blankImage(720, 520);
        }

        BufferedImage canvasImage = new BufferedImage(
            Math.max(1, canvas.getWidth()),
            Math.max(1, canvas.getHeight()),
            BufferedImage.TYPE_INT_ARGB
        );

        Graphics2D g = canvasImage.createGraphics();
        try
        {
            canvas.printAll(g);
        }
        finally
        {
            g.dispose();
        }

        Rectangle crop = resolveCropBounds(captureBounds, canvasImage.getWidth(), canvasImage.getHeight());
        if (crop == null)
        {
            return canvasImage;
        }

        return copyRegion(canvasImage, crop);
    }

    private Rectangle resolveCropBounds(Rectangle captureBounds, int canvasWidth, int canvasHeight)
    {
        if (captureBounds == null || captureBounds.width <= 0 || captureBounds.height <= 0)
        {
            return new Rectangle(0, 0, Math.max(1, canvasWidth), Math.max(1, canvasHeight));
        }

        Rectangle canvasBounds = new Rectangle(0, 0, Math.max(1, canvasWidth), Math.max(1, canvasHeight));
        Rectangle crop = captureBounds.intersection(canvasBounds);
        if (crop.width <= 0 || crop.height <= 0)
        {
            return new Rectangle(0, 0, Math.max(1, canvasWidth), Math.max(1, canvasHeight));
        }

        return crop;
    }

    private BufferedImage copyRegion(BufferedImage source, Rectangle region)
    {
        BufferedImage copy = new BufferedImage(region.width, region.height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = copy.createGraphics();
        try
        {
            g.drawImage(
                source,
                0,
                0,
                region.width,
                region.height,
                region.x,
                region.y,
                region.x + region.width,
                region.y + region.height,
                null
            );
        }
        finally
        {
            g.dispose();
        }
        return copy;
    }

    private BufferedImage blankImage(int width, int height)
    {
        BufferedImage image = new BufferedImage(Math.max(1, width), Math.max(1, height), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(24, 18, 12));
        g.fillRect(0, 0, image.getWidth(), image.getHeight());
        g.dispose();
        return image;
    }

    public static final class CaptureResult
    {
        private final String path;
        private final int width;
        private final int height;

        public CaptureResult(String path, int width, int height)
        {
            this.path = path;
            this.width = width;
            this.height = height;
        }

        public String getPath()
        {
            return path;
        }

        public int getWidth()
        {
            return width;
        }

        public int getHeight()
        {
            return height;
        }
    }
}

package com.bankvaluehistory.service;

import com.bankvaluehistory.BankValueHistoryConfig;
import com.bankvaluehistory.model.BankSnapshot;
import com.bankvaluehistory.model.BankTabSnapshot;
import com.bankvaluehistory.model.ItemSnapshot;
import java.awt.Rectangle;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.Player;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class SnapshotService
{
    private static final Logger log = LoggerFactory.getLogger(SnapshotService.class);
    private static final int PLATINUM_TOKEN_ID = 13204;
    private static final int INVENTORY_CONTAINER_ID = 93;
    private static final int EQUIPMENT_CONTAINER_ID = 94;
    private static final Pattern GE_PATTERN = Pattern.compile("\\(GE:\\s*([0-9,]+)\\)");
    private static final Pattern HA_PATTERN = Pattern.compile("\\(HA:\\s*([0-9,]+)\\)");

    private final Client client;
    private final ItemManager itemManager;
    private final BankValueHistoryConfig config;
    private final SnapshotStore snapshotStore;
    private final IconExportService iconExportService;
    private final BankImageRenderer bankImageRenderer;
    private final WikiPriceService wikiPriceService;

    private boolean dirty;
    private Instant lastBankChange = Instant.EPOCH;
    private String lastKnownProfileKey = "unknown";
    private boolean manualCapturePending;
    private Instant manualCaptureRequestedAt = Instant.EPOCH;
    private String lastCaptureStatus = "";

    @Inject
    public SnapshotService(
        Client client,
        ItemManager itemManager,
        BankValueHistoryConfig config,
        SnapshotStore snapshotStore,
        IconExportService iconExportService,
        BankImageRenderer bankImageRenderer,
        WikiPriceService wikiPriceService)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        this.snapshotStore = snapshotStore;
        this.iconExportService = iconExportService;
        this.bankImageRenderer = bankImageRenderer;
        this.wikiPriceService = wikiPriceService;
    }

    public SnapshotStore getSnapshotStore()
    {
        return snapshotStore;
    }

    public void markDirty()
    {
        dirty = true;
        lastBankChange = Instant.now();
    }

    public String getCurrentProfileKey()
    {
        Player player = client.getLocalPlayer();
        if (player != null && player.getName() != null && !player.getName().trim().isEmpty())
        {
            String resolved = player.getName().replaceAll("[^a-zA-Z0-9 _-]", "_").trim();
            if (!resolved.isEmpty())
            {
                lastKnownProfileKey = resolved;
                return resolved;
            }
        }

        return lastKnownProfileKey;
    }

    public void requestManualCapture()
    {
        manualCapturePending = true;
        manualCaptureRequestedAt = Instant.now();
        lastCaptureStatus = "Waiting for bank contents. Open your bank and enter your PIN if needed.";
    }

    public boolean isManualCapturePending()
    {
        return manualCapturePending;
    }

    public String getLastCaptureStatus()
    {
        return lastCaptureStatus;
    }

    public BankSnapshot captureNow()
    {
        return captureSnapshot(false);
    }

    public boolean maybeManualCapture()
    {
        if (!manualCapturePending)
        {
            return false;
        }

        BankSnapshot snapshot = captureSnapshot(false);
        if (snapshot != null)
        {
            manualCapturePending = false;
            lastCaptureStatus = "Snapshot captured. Refresh the browser if it is already open.";
            return true;
        }

        if (Duration.between(manualCaptureRequestedAt, Instant.now()).getSeconds() > 20)
        {
            manualCapturePending = false;
            lastCaptureStatus = isBankUiVisible()
                ? "Unable to capture yet. Enter your bank PIN if prompted and wait for contents to load."
                : "Unable to capture yet. Open your bank first, then try again.";
            return false;
        }

        lastCaptureStatus = isBankUiVisible()
            ? "Waiting for bank access. Enter your bank PIN if prompted and wait for contents to load."
            : "Waiting for bank window to open.";
        return false;
    }

    public boolean maybeAutoCapture()
    {
        return captureSnapshot(true) != null;
    }

    private BankSnapshot captureSnapshot(boolean auto)
    {
        if (auto && !config.autoCapture())
        {
            return null;
        }

        String profileKey = getCurrentProfileKey();
        if ("unknown".equals(profileKey))
        {
            if (!auto)
            {
                lastCaptureStatus = "Waiting for character data to load.";
            }
            return null;
        }

        if (auto)
        {
            if (snapshotStore.hasSnapshotForDay(profileKey, LocalDate.now()))
            {
                return null;
            }

            if (LocalTime.now().getHour() < config.captureHour())
            {
                return null;
            }

            if (dirty && Duration.between(lastBankChange, Instant.now()).getSeconds() < 3)
            {
                return null;
            }
        }

        wikiPriceService.refreshAsyncIfStale(Duration.ofMinutes(5));

        ItemContainer bank = client.getItemContainer(InventoryID.BANK);
        if (bank == null)
        {
            if (!auto)
            {
                lastCaptureStatus = isBankUiVisible()
                    ? "Bank window is open but contents are not ready. Enter your PIN if prompted."
                    : "Open your bank first.";
            }
            return null;
        }

        BankSnapshot snapshot = buildSnapshot(profileKey, bank);
        try
        {
            snapshotStore.save(snapshot);
            dirty = false;
            lastCaptureStatus = "Snapshot captured. Refresh the browser if it is already open.";
            return snapshot;
        }
        catch (IOException ex)
        {
            log.warn("Unable to save bank snapshot for {}", profileKey, ex);
            return null;
        }
    }

    private boolean isBankUiVisible()
    {
        return client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null
            || client.getWidget(InterfaceID.Bankmain.TITLE) != null
            || client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER) != null;
    }

    private BankSnapshot buildSnapshot(String profileKey, ItemContainer bank)
    {
        Instant capturedAt = Instant.now();

        Widget bankItemWidget = client.getWidget(InterfaceID.Bankmain.ITEMS);
        Rectangle captureBounds = resolveBankCaptureBounds();
        List<LayoutEntry> layoutEntries = readLayoutEntries(bankItemWidget, captureBounds);

        PendingItemsResult bankPending = buildPendingItems(profileKey, capturedAt, bank, true);
        PendingItemsResult inventoryPending = buildPendingItems(profileKey, capturedAt, client.getItemContainer(INVENTORY_CONTAINER_ID), false);
        PendingItemsResult equipmentPending = buildPendingItems(profileKey, capturedAt, client.getItemContainer(EQUIPMENT_CONTAINER_ID), false);

        long bankGe = bankPending.geTotal;
        long bankHa = bankPending.haTotal;

        ContainerPrices displayed = getDisplayedBankPrices();
        if (displayed == null)
        {
            displayed = getWidgetContainerPrices();
        }

        if (displayed != null)
        {
            bankGe = Math.max(bankGe, displayed.gePrice);
            bankHa = Math.max(bankHa, displayed.haPrice);
        }

        BankOrder bankOrder = determineBankOrder(
            bankPending.items,
            bankPending.items.size(),
            getBankTabCounts(),
            readVisibleTabItems()
        );

        List<BankTabSnapshot> tabs = buildBankTabs(bankPending.items.size(), bankOrder);
        List<ItemSnapshot> items = assignItemsToTabs(bankPending.items, tabs, layoutEntries);
        List<ItemSnapshot> inventoryItems = assignContainerItems(inventoryPending.items, -1, "Inventory");
        List<ItemSnapshot> equipmentItems = assignContainerItems(equipmentPending.items, -2, "Worn equipment");

        BankImageRenderer.CaptureResult capture = bankImageRenderer.capture(profileKey, capturedAt, captureBounds);

        long combinedGe = bankGe + inventoryPending.geTotal + equipmentPending.geTotal;
        long combinedHa = bankHa + inventoryPending.haTotal + equipmentPending.haTotal;

        return new BankSnapshot(
            profileKey,
            LocalDate.now(),
            capturedAt,
            bankGe,
            bankHa,
            bankGe,
            bankHa,
            inventoryPending.geTotal,
            inventoryPending.haTotal,
            equipmentPending.geTotal,
            equipmentPending.haTotal,
            combinedGe,
            combinedHa,
            capture.getPath(),
            capture.getWidth(),
            capture.getHeight(),
            tabs,
            items,
            inventoryItems,
            equipmentItems
        );
    }

    private PendingItemsResult buildPendingItems(String profileKey, Instant capturedAt, ItemContainer container, boolean includePlaceholders)
    {
        List<PendingItem> pending = new ArrayList<>();
        long totalGe = 0L;
        long totalHa = 0L;

        if (container == null)
        {
            return new PendingItemsResult(pending, totalGe, totalHa);
        }

        Item[] containerItems = container.getItems();
        if (containerItems == null)
        {
            return new PendingItemsResult(pending, totalGe, totalHa);
        }

        for (int slot = 0; slot < containerItems.length; slot++)
        {
            Item item = containerItems[slot];
            if (item == null)
            {
                continue;
            }

            int itemId = item.getId();
            if (itemId <= 0 || itemId == ItemID.BANK_FILLER)
            {
                continue;
            }

            int quantity = Math.max(0, item.getQuantity());
            boolean placeholder = includePlaceholders && quantity == 0;
            if (!includePlaceholders && quantity <= 0)
            {
                continue;
            }

            int canonicalItemId = itemManager.canonicalize(itemId);
            String name = itemManager.getItemComposition(itemId).getName();

            int geUnit = 0;
            int haUnit = 0;
            long geTotal = 0L;
            long haTotal = 0L;

            if (!placeholder)
            {
                geUnit = Math.max(0, itemManager.getItemPrice(itemId));
                haUnit = Math.max(0, getHaPrice(itemId));
                geTotal = (long) geUnit * quantity;
                haTotal = (long) haUnit * quantity;
            }

            String iconPath = "/icons/" + canonicalItemId + ".png";
            if (config.exportIcons())
            {
                iconPath = iconExportService.exportSnapshotIcon(
                    profileKey,
                    capturedAt,
                    itemId,
                    canonicalItemId,
                    quantity,
                    placeholder
                );
            }

            pending.add(new PendingItem(
                itemId,
                canonicalItemId,
                name,
                quantity,
                geUnit,
                geTotal,
                haUnit,
                haTotal,
                iconPath,
                placeholder,
                slot
            ));

            totalGe += geTotal;
            totalHa += haTotal;
        }

        return new PendingItemsResult(pending, totalGe, totalHa);
    }

    private List<ItemSnapshot> assignContainerItems(List<PendingItem> pending, int tabIndex, String tabName)
    {
        List<ItemSnapshot> items = new ArrayList<>(pending.size());
        for (PendingItem item : pending)
        {
            items.add(new ItemSnapshot(
                item.itemId,
                item.canonicalItemId,
                item.name,
                item.quantity,
                item.geUnitPrice,
                item.geTotal,
                item.haUnitPrice,
                item.haTotal,
                item.sourceSlotIndex,
                tabIndex,
                tabName,
                item.iconPath,
                item.placeholder,
                -1,
                -1,
                0,
                0
            ));
        }
        return items;
    }

    private Rectangle resolveBankCaptureBounds()
    {
        Rectangle union = null;

        union = union(union, getWidgetBounds(InterfaceID.Bankmain.UNIVERSE));
        union = union(union, getWidgetBounds(InterfaceID.Bankmain.ITEMS_CONTAINER));
        union = union(union, getWidgetBounds(InterfaceID.Bankmain.TABS));
        union = union(union, getWidgetBounds(InterfaceID.Bankmain.TITLE));
        union = union(union, getWidgetBounds(InterfaceID.Bankmain.ITEMS));

        if (union == null)
        {
            return null;
        }

        return new Rectangle(
            union.x,
            union.y,
            Math.max(1, union.width),
            Math.max(1, union.height)
        );
    }

    private Rectangle getWidgetBounds(int componentId)
    {
        Widget widget = client.getWidget(componentId);
        if (widget == null)
        {
            return null;
        }

        Rectangle bounds = widget.getBounds();
        if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
        {
            return null;
        }

        return new Rectangle(bounds);
    }

    private Rectangle union(Rectangle a, Rectangle b)
    {
        if (a == null)
        {
            return b == null ? null : new Rectangle(b);
        }

        if (b == null)
        {
            return new Rectangle(a);
        }

        return a.union(b);
    }

    private ContainerPrices getDisplayedBankPrices()
    {
        Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (title == null)
        {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        appendWidgetText(title, sb);
        String allText = sb.toString();
        if (allText.isEmpty())
        {
            return null;
        }

        Long ge = parseExactBankValue(allText, GE_PATTERN);
        Long ha = parseExactBankValue(allText, HA_PATTERN);
        if (ge == null && ha == null)
        {
            return null;
        }

        return new ContainerPrices(ge != null ? ge : 0L, ha != null ? ha : 0L);
    }

    private void appendWidgetText(Widget widget, StringBuilder sb)
    {
        if (widget == null)
        {
            return;
        }

        String text = widget.getText();
        if (text != null && !text.isEmpty())
        {
            if (sb.length() > 0)
            {
                sb.append(' ');
            }
            sb.append(text);
        }

        Widget[] children = widget.getChildren();
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            appendWidgetText(child, sb);
        }
    }

    private Long parseExactBankValue(String text, Pattern pattern)
    {
        Matcher matcher = pattern.matcher(text);
        if (!matcher.find())
        {
            return null;
        }

        try
        {
            return Long.parseLong(matcher.group(1).replace(",", "").trim());
        }
        catch (Exception ex)
        {
            return null;
        }
    }

    private ContainerPrices getWidgetContainerPrices()
    {
        Widget widget = client.getWidget(InterfaceID.Bankmain.ITEMS);
        ItemContainer itemContainer = client.getItemContainer(InventoryID.BANK);
        if (widget == null || itemContainer == null)
        {
            return null;
        }

        Widget[] children = widget.getChildren();
        if (children == null)
        {
            return null;
        }

        long geTotal = 0L;
        long haTotal = 0L;
        int max = Math.min(itemContainer.size(), children.length);

        for (int i = 0; i < max; i++)
        {
            Widget child = children[i];
            if (child == null || child.isSelfHidden() || child.getItemId() <= -1)
            {
                continue;
            }

            int itemId = child.getItemId();
            int quantity = child.getItemQuantity();
            geTotal += (long) itemManager.getItemPrice(itemId) * quantity;
            haTotal += (long) getHaPrice(itemId) * quantity;
        }

        return new ContainerPrices(geTotal, haTotal);
    }

    private int getHaPrice(int itemId)
    {
        switch (itemId)
        {
            case ItemID.COINS:
                return 1;
            case PLATINUM_TOKEN_ID:
                return 1000;
            default:
                return itemManager.getItemComposition(itemId).getHaPrice();
        }
    }

    private int[] getBankTabCounts()
    {
        return new int[] {
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_1)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_2)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_3)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_4)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_5)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_6)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_7)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_8)),
            Math.max(0, client.getVarbitValue(VarbitID.BANK_TAB_9))
        };
    }

    private List<BankTabSnapshot> buildBankTabs(int totalSlots, BankOrder bankOrder)
    {
        int[] counts = getBankTabCounts();
        int assigned = 0;
        for (int count : counts)
        {
            assigned += count;
        }
        assigned = Math.min(totalSlots, assigned);

        int mainCount = Math.max(0, totalSlots - assigned);
        List<BankTabSnapshot> tabs = new ArrayList<>();

        if (bankOrder == BankOrder.MAIN_FIRST)
        {
            tabs.add(new BankTabSnapshot(0, "Main", mainCount));
        }

        int remaining = totalSlots - mainCount;
        for (int i = 0; i < counts.length; i++)
        {
            int count = Math.min(counts[i], Math.max(0, remaining));
            tabs.add(new BankTabSnapshot(i + 1, "Tab " + (i + 1), count));
            remaining -= count;
        }

        if (bankOrder == BankOrder.MAIN_LAST)
        {
            tabs.add(new BankTabSnapshot(0, "Main", mainCount));
        }

        return tabs;
    }

    private BankOrder determineBankOrder(
        List<PendingItem> pending,
        int totalSlots,
        int[] counts,
        List<VisibleItem> visibleTabItems)
    {
        int currentTab = client.getVarbitValue(VarbitID.BANK_CURRENTTAB);
        if (currentTab >= 1 && currentTab <= counts.length && !visibleTabItems.isEmpty())
        {
            int mainCount = Math.max(0, totalSlots - sum(counts));
            int targetCount = Math.max(0, counts[currentTab - 1]);
            if (targetCount == visibleTabItems.size())
            {
                int mainFirstStart = mainCount + sum(counts, 0, currentTab - 1);
                int mainLastStart = sum(counts, 0, currentTab - 1);

                boolean mainFirstMatches = matchesVisibleSegment(pending, visibleTabItems, mainFirstStart);
                boolean mainLastMatches = matchesVisibleSegment(pending, visibleTabItems, mainLastStart);

                if (mainLastMatches && !mainFirstMatches)
                {
                    return BankOrder.MAIN_LAST;
                }

                if (mainFirstMatches && !mainLastMatches)
                {
                    return BankOrder.MAIN_FIRST;
                }
            }
        }

        return BankOrder.MAIN_LAST;
    }

    private List<VisibleItem> readVisibleTabItems()
    {
        List<VisibleItem> visible = new ArrayList<>();
        Widget widget = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (widget == null)
        {
            return visible;
        }

        Widget[] children = widget.getChildren();
        if (children == null)
        {
            return visible;
        }

        for (Widget child : children)
        {
            if (child == null || child.isSelfHidden())
            {
                continue;
            }

            int itemId = child.getItemId();
            int quantity = Math.max(0, child.getItemQuantity());
            if (itemId <= 0 || itemId == ItemID.BANK_FILLER)
            {
                continue;
            }

            visible.add(new VisibleItem(itemId, quantity));
        }

        return visible;
    }

    private List<LayoutEntry> readLayoutEntries(Widget bankItemWidget, Rectangle captureBounds)
    {
        List<LayoutEntry> entries = new ArrayList<>();
        if (bankItemWidget == null || captureBounds == null)
        {
            return entries;
        }

        Widget[] children = bankItemWidget.getChildren();
        if (children == null)
        {
            return entries;
        }

        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }

            int itemId = child.getItemId();
            if (itemId <= 0 || itemId == ItemID.BANK_FILLER)
            {
                continue;
            }

            Rectangle bounds = child.getBounds();
            if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
            {
                continue;
            }

            entries.add(new LayoutEntry(
                itemId,
                Math.max(0, child.getItemQuantity()),
                bounds.x - captureBounds.x,
                bounds.y - captureBounds.y,
                bounds.width,
                bounds.height
            ));
        }

        return entries;
    }

    private boolean matchesVisibleSegment(List<PendingItem> pending, List<VisibleItem> visibleItems, int startIndex)
    {
        if (startIndex < 0 || startIndex + visibleItems.size() > pending.size())
        {
            return false;
        }

        for (int offset = 0; offset < visibleItems.size(); offset++)
        {
            PendingItem snapshotItem = pending.get(startIndex + offset);
            VisibleItem visibleItem = visibleItems.get(offset);
            if (snapshotItem.itemId != visibleItem.itemId || snapshotItem.quantity != visibleItem.quantity)
            {
                return false;
            }
        }

        return true;
    }

    private int sum(int[] counts)
    {
        return sum(counts, 0, counts.length);
    }

    private int sum(int[] counts, int startInclusive, int endExclusive)
    {
        int total = 0;
        for (int i = startInclusive; i < endExclusive; i++)
        {
            total += Math.max(0, counts[i]);
        }
        return total;
    }

    private List<ItemSnapshot> assignItemsToTabs(
        List<PendingItem> pending,
        List<BankTabSnapshot> tabs,
        List<LayoutEntry> layoutEntries)
    {
        List<ItemSnapshot> items = new ArrayList<>(pending.size());
        int cursor = 0;
        int layoutCursor = 0;

        for (BankTabSnapshot tab : tabs)
        {
            for (int i = 0; i < tab.getCount() && cursor < pending.size(); i++)
            {
                PendingItem item = pending.get(cursor);
                LayoutEntry layout = matchLayoutEntry(item, layoutEntries, layoutCursor);
                if (layout != null)
                {
                    layoutCursor = layout.nextCursor;
                }

                items.add(new ItemSnapshot(
                    item.itemId,
                    item.canonicalItemId,
                    item.name,
                    item.quantity,
                    item.geUnitPrice,
                    item.geTotal,
                    item.haUnitPrice,
                    item.haTotal,
                    cursor,
                    tab.getIndex(),
                    tab.getName(),
                    item.iconPath,
                    item.placeholder,
                    layout != null ? layout.x : -1,
                    layout != null ? layout.y : -1,
                    layout != null ? layout.w : 0,
                    layout != null ? layout.h : 0
                ));
                cursor++;
            }
        }

        while (cursor < pending.size())
        {
            PendingItem item = pending.get(cursor);
            LayoutEntry layout = matchLayoutEntry(item, layoutEntries, layoutCursor);
            if (layout != null)
            {
                layoutCursor = layout.nextCursor;
            }

            items.add(new ItemSnapshot(
                item.itemId,
                item.canonicalItemId,
                item.name,
                item.quantity,
                item.geUnitPrice,
                item.geTotal,
                item.haUnitPrice,
                item.haTotal,
                cursor,
                0,
                "Main",
                item.iconPath,
                item.placeholder,
                layout != null ? layout.x : -1,
                layout != null ? layout.y : -1,
                layout != null ? layout.w : 0,
                layout != null ? layout.h : 0
            ));
            cursor++;
        }

        return items;
    }

    private LayoutEntry matchLayoutEntry(PendingItem item, List<LayoutEntry> entries, int startCursor)
    {
        for (int i = startCursor; i < entries.size(); i++)
        {
            LayoutEntry entry = entries.get(i);
            if (entry.itemId == item.itemId && entry.quantity == item.quantity)
            {
                return new LayoutEntry(entry.itemId, entry.quantity, entry.x, entry.y, entry.w, entry.h, i + 1);
            }
        }

        for (int i = startCursor; i < entries.size(); i++)
        {
            LayoutEntry entry = entries.get(i);
            if (entry.itemId == item.itemId)
            {
                return new LayoutEntry(entry.itemId, entry.quantity, entry.x, entry.y, entry.w, entry.h, i + 1);
            }
        }

        return null;
    }

    private static class PendingItem
    {
        private final int itemId;
        private final int canonicalItemId;
        private final int quantity;
        private final int geUnitPrice;
        private final int haUnitPrice;
        private final String name;
        private final String iconPath;
        private final long geTotal;
        private final long haTotal;
        private final boolean placeholder;
        private final int sourceSlotIndex;

        private PendingItem(
            int itemId,
            int canonicalItemId,
            String name,
            int quantity,
            int geUnitPrice,
            long geTotal,
            int haUnitPrice,
            long haTotal,
            String iconPath,
            boolean placeholder,
            int sourceSlotIndex)
        {
            this.itemId = itemId;
            this.canonicalItemId = canonicalItemId;
            this.name = name;
            this.quantity = quantity;
            this.geUnitPrice = geUnitPrice;
            this.geTotal = geTotal;
            this.haUnitPrice = haUnitPrice;
            this.haTotal = haTotal;
            this.iconPath = iconPath;
            this.placeholder = placeholder;
            this.sourceSlotIndex = sourceSlotIndex;
        }
    }

    private static class PendingItemsResult
    {
        private final List<PendingItem> items;
