        private final long haPrice;

        private ContainerPrices(long gePrice, long haPrice)
        {
            this.gePrice = gePrice;
            this.haPrice = haPrice;
        }
    }

    private enum BankOrder
    {
        MAIN_FIRST,
        MAIN_LAST
    }
}

